<div class="mb-6"><p class="mb-2 text-xs font-bold uppercase tracking-[.16em] text-brand-600 dark:text-brand-400">CONFIANCE & SÉCURITÉ</p><h1 class="text-title-md font-bold text-gray-800 dark:text-white/90">Signalements</h1><p class="mt-2 text-theme-sm text-gray-500 dark:text-gray-400">Exemples de signalements pour illustrer le processus de suivi.</p></div>
<div class="grid grid-cols-1 gap-4 lg:grid-cols-2"><?php foreach ($reports as $report): ?><article class="rounded-2xl border border-gray-200 bg-white p-5 dark:border-gray-800 dark:bg-white/[0.03]"><div class="flex items-start justify-between gap-3"><div><span class="text-xs font-bold uppercase tracking-wider text-gray-400"><?= e($report['id']) ?></span><h2 class="mt-2 text-theme-xl font-bold text-gray-800 dark:text-white/90"><?= e($report['subject']) ?></h2></div><span class="rounded-full px-2.5 py-1 text-xs font-semibold <?= $report['status'] === 'Ouvert' ? 'bg-warning-50 text-warning-700' : 'bg-success-50 text-success-700' ?>"><?= e($report['status']) ?></span></div><p class="mt-3 text-theme-sm text-gray-600 dark:text-gray-300"><?= e($report['reason']) ?></p><?php if ($report['status'] === 'Ouvert'): ?><form class="mt-4" method="post" action="<?= e(route('admin/reports')) ?>"><?= csrf_input() ?><input type="hidden" name="report_id" value="<?= e($report['id']) ?>"><button class="rounded-lg bg-brand-600 px-4 py-2.5 text-xs font-semibold text-white hover:bg-brand-700" type="submit">Marquer comme traité</button></form><?php endif; ?></article><?php endforeach; ?></div>
